const transformSchema = (input: any): any => {
  const newSchema: any = {
    url: input.url
  }

  // Check if method exists and add it to the new schema
  if (input.method) {
    newSchema.method = input.method
  }

  // Convert headers array to record if headers exist
  if (input.headers && Array.isArray(input.headers)) {
    newSchema.headers = input.headers.reduce((acc: Record<string, string>, header: any) => {
      acc[header.key] = header.value
      return acc
    }, {})
  }

  // Convert body based on its type
  if (input.body) {
    switch (input.body.bodyType) {
      case 'JSON':
        // Ensure jsonBody exists and handle both object and array cases
        if (Array.isArray(input.body.jsonBody)) {
          newSchema.data = input.body.jsonBody.reduce((acc: any, obj: any) => {
            acc[obj.a] = 'example' // You can replace 'example' with the appropriate value
            return acc
          }, {})
        } else if (typeof input.body.jsonBody === 'object' && input.body.jsonBody !== null) {
          // If jsonBody is an object, directly assign it to data
          newSchema.data = input.body.jsonBody
        } else {
          newSchema.data = {} // Fallback if jsonBody is not an object
        }
        break
      case 'Form':
        // Ensure formBody exists and is an array before reducing
        if (Array.isArray(input.body.formBody)) {
          newSchema.data = input.body.formBody.reduce((acc: Record<string, string>, field: any) => {
            acc[field.key] = field.value
            return acc
          }, {})
        } else {
          newSchema.data = {} // Fallback if formBody is not an array
        }
        break
      case 'Text':
        // For text body, assign the text directly
        if (typeof input.body.textBody === 'string') {
          newSchema.data = input.body.textBody
        } else {
          newSchema.data = '' // Fallback if textBody is not a string
        }
        break
      default:
        newSchema.data = undefined // No body
    }
  }

  // Optional: Handle params or other fields if needed
  if (input.params) {
    newSchema.params = input.params
  }

  return newSchema
}

// Transform input to workflow.request:newSchema
workflow.request = transformSchema(workflow.inputs)

