const backedOffAxios = async (config, retries = 5, delay = 1000, attempt = 0) => {
  try {
    const response = await axios.request(config)

    return response
  } catch (error: AxiosError) {
    if (error.response && error.response.status === 429 && attempt < retries) {
      const backoff = delay * Math.pow(2, attempt)

      console.log(`Request rate limited, retrying in ${backoff} ms`)

      await new Promise((resolve) => setTimeout(resolve, backoff))

      return backedOffAxios(config, retries, delay, attempt + 1)
    }

    throw error
  }
}

try {
  workflow.response = await backedOffAxios(workflow.request)
} catch (error: AxiosError) {
  workflow.error = error
}

