/**

* This action calculates the level based on the quiz score

* and stores it in temp.level so it can be used in other nodes.

*/

const score = temp.score || 0; // make sure score exists

let level = "";

if (score >= 0 && score <= 7) {

  level = "Beginner";

} else if (score >= 8 && score <= 12) {

  level = "Intermediate";

} else if (score >= 13 && score <= 15) {

  level = "Advanced";

} else {

  level = "Invalid score";

}

// Store level in temp for next nodes

temp.level = level;

// Optional: return text to display directly in chat

return `Your score is ${score}/15. Level: ${level}`;

